GLOSSARY.push(
  { k: ['positive liberty'], d: 'Freedom as the real ability to act and live as one chooses, which may require resources such as money, education or healthcare.' },
  { k: ['negative liberty'], d: 'Freedom as the absence of interference: no one, including the state, stops you from acting.' },
  { k: ['capability approach'], d: "Amartya Sen's and Martha Nussbaum's idea that justice should be judged by what people are actually able to do and be, not just the resources they have." },
  { k: ['restorative justice'], d: 'An approach to crime that brings offenders, victims and communities together to repair harm, rather than relying on punishment alone.' },
  { k: ['pre-trial detention'], d: 'Holding a suspect in custody before a court has decided whether they are guilty.' },
  { k: ['citizens\' assembly', 'citizens\' assemblies'], d: 'A group of ordinary people chosen at random to study and decide or advise on a political question.' },
  { k: ['self-determination'], d: 'The right of a people to decide its own political status and form of government.' },
  { k: ['stateless'], d: 'Not recognised as a citizen by any country.' },
  { k: ['cooperative', 'cooperatives'], d: 'A business owned and run democratically by its members, such as its workers or customers.' },
  { k: ['global minimum tax'], d: 'An international agreement that large companies should pay at least a set rate of tax, wherever they are based.' },
  { k: ['precautionary principle'], d: 'The idea that when an action might cause serious harm, the burden of proving it is safe lies with those who want to take it.' },
);

